const filterValue = ($('View List (GET)').first().json.query && $('View List (GET)').first().json.query.store) || '';

const rows = $input.all().map(function(i) { return i.json; }).filter(function(r) { return r && r.id; });
const unchecked = rows.filter(function(r) { return !r.checked; });
const checked = rows.filter(function(r) { return r.checked; });

function esc(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function itemRow(r) {
  var label = esc(r.item) + (r.quantity ? ' (' + esc(r.quantity) + ')' : '') + (r.category ? ' — ' + esc(r.category) : '') + (r.store ? ' @ ' + esc(r.store) : '');
  return '<form method="POST" action="/webhook/groceries/check" class="row">' +
    '<input type="hidden" name="id" value="' + r.id + '">' +
    '<input type="hidden" name="current_filter" value="' + esc(filterValue) + '">' +
    '<button type="submit" class="check-btn">☐ ' + label + '</button>' +
    '</form>';
}

function checkedRow(r) {
  return '<div class="row checked-row">☑ <span class="strike">' + esc(r.item) + '</span></div>';
}

var uncheckedHtml = unchecked.length
  ? unchecked.map(itemRow).join('\n')
  : '<p class="empty">Nothing to buy — add something below.</p>';

var checkedHtml = '<details class="checked-details"><summary>Checked off (' + checked.length + ')</summary>' +
  (checked.length ? checked.map(checkedRow).join('\n') : '<p class="empty">Nothing checked off yet.</p>') +
  '</details>';

var filterForm = '<form method="GET" action="/webhook/groceries" class="filter-form">' +
  '<input type="text" name="store" value="' + esc(filterValue) + '" placeholder="Filter by store">' +
  '<button type="submit">Filter</button>' +
  (filterValue ? '<a class="clear-link" href="/webhook/groceries">Clear</a>' : '') +
  '</form>';

var html = '<!DOCTYPE html><html lang="en"><head>' +
  '<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
  '<title>Grocery List</title>' +
  '<style>' +
  ':root{color-scheme:light dark;} body{font-family:-apple-system,system-ui,sans-serif;max-width:480px;margin:0 auto;padding:16px;}' +
  'h1{font-size:1.4rem;}' +
  '.filter-form{display:flex;gap:8px;margin-bottom:16px;align-items:center;}' +
  '.filter-form input{flex:1;padding:8px;font-size:0.95rem;border-radius:8px;border:1px solid rgba(128,128,128,.3);background:transparent;color:inherit;}' +
  '.filter-form button{padding:8px 12px;border-radius:8px;border:none;background:#2563eb;color:white;}' +
  '.clear-link{font-size:0.85rem;opacity:.7;text-decoration:none;color:inherit;white-space:nowrap;}' +
  'form.row{margin:8px 0;}' +
  '.check-btn{width:100%;text-align:left;font-size:1.05rem;padding:12px;border-radius:10px;border:1px solid rgba(128,128,128,.3);background:transparent;color:inherit;}' +
  '.checked-row{padding:8px 12px;opacity:.5;} .strike{text-decoration:line-through;} .empty{opacity:.6;}' +
  '.checked-details summary{cursor:pointer;font-size:1rem;opacity:.7;margin-top:32px;padding:8px 0;}' +
  '.add-form{margin-top:24px;padding-top:16px;border-top:1px solid rgba(128,128,128,.3);display:flex;flex-direction:column;gap:8px;}' +
  '.add-form input{padding:10px;font-size:1rem;border-radius:8px;border:1px solid rgba(128,128,128,.3);background:transparent;color:inherit;}' +
  '.add-form button{padding:12px;font-size:1rem;border-radius:8px;border:none;background:#2563eb;color:white;}' +
  '</style></head><body>' +
  '<h1>Grocery List</h1>' +
  filterForm +
  uncheckedHtml +
  checkedHtml +
  '<form class="add-form" method="POST" action="/webhook/groceries/add">' +
  '<input type="hidden" name="current_filter" value="' + esc(filterValue) + '">' +
  '<input type="text" name="item" placeholder="Item (e.g. Milk)" required>' +
  '<input type="text" name="quantity" placeholder="Quantity (optional)">' +
  '<input type="text" name="category" placeholder="Category (optional)">' +
  '<input type="text" name="store" placeholder="Store (optional)">' +
  '<button type="submit">Add item</button>' +
  '</form>' +
  '</body></html>';

return [{ json: { html: html } }];

